import { supabase,requirePlayer,toast } from "./flow-common.js";
import { attemptStats,missingQuestionIds,percentage } from "./quiz-engine.mjs";
const $=s=>document.querySelector(s),lessonCode=new URLSearchParams(location.search).get("lesson")||"ai-ethics-m6-01";
const state={user:null,lesson:null,quiz:null,questions:[],answers:{},current:0,attempts:[],result:null,reward:null,rewardError:null,claiming:false,submitting:false,submissionId:crypto.randomUUID()};
const esc=(v="")=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);
function renderHistory(){const s=attemptStats(state.attempts);$("#quiz-history").innerHTML=s.latest?`<span>ครั้งล่าสุด <b>${s.latest.score}/${s.latest.max_score}</b></span><span>คะแนนสูงสุด <b>${s.best.score}/${s.best.max_score}</b></span><span class="${s.everPassed?"passed":""}">${s.everPassed?"✓ ผ่านแล้ว":"ยังไม่ผ่าน"}</span>`:"<span>ยังไม่มีประวัติการทำแบบทดสอบ</span>";}
function renderQuestion(){const q=state.questions[state.current],chosen=state.answers[q.id]||[],multi=q.question_type==="multiple";const done=Object.values(state.answers).filter(x=>x.length).length;$("#quiz-app").innerHTML=`<div class="quiz-progress"><span><i style="width:${done/state.questions.length*100}%"></i></span><b>${done}/${state.questions.length} ข้อ</b></div><div class="quiz-question-meta"><span>${q.learning_objective_id}</span><em>ข้อ ${state.current+1} จาก ${state.questions.length}</em></div><h2>${esc(q.question_text)}</h2>${multi?'<p class="quiz-instruction">เลือกทุกคำตอบที่ถูกต้อง</p>':""}<div class="quiz-options">${q.options.map((o,i)=>`<button type="button" data-option="${o.id}" class="${chosen.includes(o.id)?"selected":""}"><span>${String.fromCharCode(65+i)}</span>${esc(o.label)}</button>`).join("")}</div><footer><button data-action="prev" ${state.current===0?"disabled":""}>← ย้อนกลับ</button><div class="quiz-dots">${state.questions.map((x,i)=>`<i class="${state.answers[x.id]?.length?"done":""} ${i===state.current?"active":""}"></i>`).join("")}</div>${state.current===state.questions.length-1?'<button class="primary" data-action="submit">ส่งคำตอบ</button>':'<button class="primary" data-action="next">ถัดไป →</button>'}</footer>`;}
function loName(id){return({LO1:"AI Bias และ Data Bias",LO2:"Algorithmic Fairness",LO3:"Transparency และ Human Oversight",LO4:"Responsible AI"})[id]||id;}
function renderResult(){const r=state.result,p=percentage(r.score,r.max_score),feedback=r.feedback||[];$("#quiz-app").innerHTML=`<section class="quiz-result ${r.passed?"passed":"retry"}"><div class="quiz-score-ring"><strong>${r.score}</strong><span>/ ${r.max_score}</span></div><small>${p}%</small><h2>${r.passed?"ภารกิจสำเร็จ! คุณผ่านการประเมินความรู้ของ AI District แล้ว":"อีกนิดเดียว! ลองทบทวนหัวข้อที่ยังไม่เข้าใจ แล้วกลับมาทดสอบอีกครั้ง"}</h2><p>${r.passed?"ผลผ่านถูกยืนยันโดยฐานข้อมูลแล้ว ระบบกำลังตรวจสิทธิ์รางวัลถาวร":"คะแนนครั้งนี้ถูกเก็บไว้ คุณสามารถทบทวนเฉพาะฉากที่เกี่ยวข้องได้"}</p>${state.rewardError?`<div class="reward-claim-error">รับรางวัลยังไม่สำเร็จ แต่ผลสอบผ่านยังถูกเก็บไว้<button class="reward-claim-retry" data-action="claim-reward">ลองรับรางวัลอีกครั้ง</button></div>`:""}<div class="lo-results">${Object.entries(r.learning_objective_results).map(([id,x])=>`<div><b>${loName(id)}</b><span>${x.correct}/${x.total}</span><i style="width:${x.correct/x.total*100}%"></i></div>`).join("")}</div>${feedback.filter(x=>!x.correct).length?`<div class="remediation-list"><h3>หัวข้อที่ควรทบทวน</h3>${feedback.filter(x=>!x.correct).map(x=>`<a href="lesson-player.html?lesson=${lessonCode}&scene=${x.remediationSceneId}&return=quiz">ทบทวนข้อ ${x.questionId.replace("m6q","")} · ${esc(x.explanation)}</a>`).join("")}</div>`:'<div class="quiz-strength">ทำได้ดีในทุก Learning Objective แต่ยังควรนำหลักคิดไปฝึกกับสถานการณ์อื่น</div>'}<div class="quiz-result-actions"><button data-action="retake">ทำแบบทดสอบอีกครั้ง</button>${r.passed?'<a href="card-inventory.html">ดูคลังการ์ด</a>':""}<a href="learning.html">กลับ Learning World</a></div></section>`;}
function showReward(reward){const already=reward.status==="ALREADY_UNLOCKED";$("#reward-reveal-content").innerHTML=`<section class="reward-reveal-card"><small>${esc(state.lesson.title)}</small><h2>${already?"คุณมีการ์ดใบนี้แล้ว":"ปลดล็อกการ์ดสำเร็จ!"}</h2><div class="reward-card-visual"><span>AD</span></div><h3>${esc(reward.card_name)}</h3><div class="reward-reveal-meta"><span>${esc(reward.card_type)}</span><span>${reward.en_cost} EN</span></div><p>${esc(reward.description)}</p><div class="reward-reveal-actions"><a href="card-inventory.html">ดูในคลังการ์ด</a><button type="button" data-close-reward>กลับสู่โลก AI</button></div></section>`;$("#reward-reveal").showModal();}
async function claimReward(){if(state.claiming)return;state.claiming=true;state.rewardError=null;const{data,error}=await supabase.rpc("claim_lesson_reward",{p_lesson_code:lessonCode});state.claiming=false;if(error){state.rewardError=error;toast("รับรางวัลยังไม่สำเร็จ กรุณาลองใหม่","error");if(state.result)renderResult();return;}const reward=Array.isArray(data)?data[0]:data;if(!reward||reward.status==="NOT_ELIGIBLE"){state.rewardError=new Error("ยังไม่ผ่านเกณฑ์รับรางวัล");if(state.result)renderResult();return;}state.reward=reward;showReward(reward);}
function selectOption(id){const q=state.questions[state.current],now=state.answers[q.id]||[];state.answers[q.id]=q.question_type==="multiple"?(now.includes(id)?now.filter(x=>x!==id):[...now,id]):[id];renderQuestion();}
async function submit(){const missing=missingQuestionIds(state.questions,state.answers);if(missing.length){const first=state.questions.findIndex(q=>q.id===missing[0]);state.current=first;renderQuestion();toast(`ยังไม่ได้ตอบ ${missing.length} ข้อ`,"error");return;}if(!confirm("ยืนยันส่งคำตอบ? หลังส่งแล้วคะแนนครั้งนี้จะไม่เปลี่ยนแปลง"))return;if(state.submitting)return;state.submitting=true;const {data,error}=await supabase.rpc("submit_lesson_quiz",{p_quiz_id:state.quiz.id,p_answers:state.answers,p_submission_id:state.submissionId});state.submitting=false;if(error){toast(error.message,"error");return;}state.result=Array.isArray(data)?data[0]:data;state.attempts.unshift(state.result);renderHistory();renderResult();if(state.result.passed)await claimReward();}
function retake(){state.answers={};state.current=0;state.result=null;state.submissionId=crypto.randomUUID();renderQuestion();}
$("#quiz-app").addEventListener("click",e=>{const o=e.target.closest("[data-option]")?.dataset.option,a=e.target.closest("[data-action]")?.dataset.action;if(o)selectOption(o);else if(a==="prev"){state.current--;renderQuestion();}else if(a==="next"){state.current++;renderQuestion();}else if(a==="submit")submit();else if(a==="retake")retake();else if(a==="claim-reward")claimReward();});
$("#reward-reveal").addEventListener("click",e=>{if(e.target.closest("[data-close-reward]")){$("#reward-reveal").close();location.assign("learning.html");}});
document.addEventListener("keydown",e=>{if(e.altKey&&e.key==="ArrowLeft"&&state.current>0){state.current--;renderQuestion();}if(e.altKey&&e.key==="ArrowRight"&&state.current<state.questions.length-1){state.current++;renderQuestion();}});
try{const p=await requirePlayer();state.user=p.user;const{data:lesson,error:le}=await supabase.from("learning_lessons").select("id,code,title").eq("code",lessonCode).single();if(le)throw le;state.lesson=lesson;const{data:quiz,error:qe}=await supabase.from("lesson_quizzes").select("id,code,title,passing_score,total_questions").eq("lesson_id",lesson.id).eq("is_active",true).single();if(qe)throw qe;state.quiz=quiz;const[{data:questions,error:qse},{data:attempts,error:ae}]=await Promise.all([supabase.from("quiz_questions").select("id,learning_objective_id,question_type,question_text,options,position").eq("quiz_id",quiz.id).order("position"),supabase.from("quiz_attempts").select("id,score,max_score,passed,learning_objective_results,feedback,submitted_at").eq("quiz_id",quiz.id).order("submitted_at",{ascending:false})]);if(qse||ae)throw qse||ae;state.questions=questions;state.attempts=attempts;$("#quiz-title").textContent=quiz.title;renderHistory();renderQuestion();if(attempts.some((attempt)=>attempt.passed))await claimReward();}catch(error){toast(error.message,"error");$("#quiz-app").innerHTML='<div class="quiz-load-error"><h2>เปิดแบบทดสอบไม่สำเร็จ</h2><p>กลับไปยังบทเรียนแล้วลองอีกครั้ง</p></div>';}
